ftmb6a TimesNewRomanPSMT-Bold <timesbd.pfb <T2A.enc
ftmbi6a TimesNewRomanPSMT-BoldItalic <timesbi.pfb <T2A.enc
ftmro6a TimesNewRomanPSMT-Oblique <timesi.pfb <T2A.enc
ftmbo6a TimesNewRomanPSMT-BoldOblique <timesbi.pfb <T2A.enc
ftmrc6a TimesNewRomanPSMT-SC <times.pfb <T2A.enc

% ERKurier fonts
ferr6a ERKurierPSMT <ercour.pfb <T2A.enc
ferri6a ERKurierPSMT-Italic <ercouri.pfb <T2A.enc
ferb6a ERKurierPSMT-Bold <ercourb.pfb <T2A.enc
